validation.probe:
final readonly class CreditLimit
{
    public function __construct(public int $cents)
    {
        if ($cents < 0) {
            throw new InvalidArgumentException('negative limit');
        }
    }
}
try {
    new CreditLimit(-1);
} catch (InvalidArgumentException) {
    echo 'rejected:';
}
echo (new CreditLimit(0))->cents;
